using System;
using System.Collections.Generic;
using System.Diagnostics.Eventing.Reader;
using System.IO;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Xml.Linq;

namespace BaitNotes
{
    public class Scammer
    {
        public required string Name { get; set; }
        public required string Number { get; set; }
        public ScammerStatus Status { get; set; }
        public required string ImageBase64 { get; set; }
    }

    public enum ScammerStatus
    {
        Operating,
        BusyLine,
        Closed,
        PermanentlyShutdown
    }

    public partial class MainWindow : Window
    {
        private readonly Dictionary<string, string> DefaultImages = new()
        {
            { "blue", "" },
            { "green", "" },
            { "red", "" },
            { "yellow", "" },
            { "purple", "" },
            { "gray", "" },
        };

        public MainWindow()
        {
            InitializeComponent();
            LoadScammersFromXml("scammers.xml");
        }


        private void LoadScammersFromXml(string xmlPath)
        {
            if (!File.Exists(xmlPath))
            {
                MessageBox.Show("Scammers.xml not found!");
                return;
            }

            var doc = XDocument.Load(xmlPath);
            var scammers = doc.Descendants("Scammer").Select(x =>
            {
                string statusText = ((string?)x.Element("Status")) ?? "Operating";
                ScammerStatus parsedStatus;

                if (!Enum.TryParse(statusText.Replace(" ", ""), true, out parsedStatus))
                    parsedStatus = ScammerStatus.Operating;

                return new Scammer
                {
                    Name = (string?)x.Element("Name") ?? string.Empty,
                    Number = (string?)x.Element("Number") ?? string.Empty,
                    Status = parsedStatus,
                    ImageBase64 = (string?)x.Element("ImageBase64")
                };
            }).ToList();


            if (scammers.Count == 0)
            {
                var placeholder = new TextBlock
                {
                    Text = "Your contacts will appear here soon.",
                    Foreground = new SolidColorBrush(Color.FromRgb(180, 180, 180)),
                    FontSize = 16,
                    FontStyle = FontStyles.Italic,
                    HorizontalAlignment = HorizontalAlignment.Center,
                    VerticalAlignment = VerticalAlignment.Center,
                    TextAlignment = TextAlignment.Center,
                    Margin = new Thickness(20),
                    TextWrapping = TextWrapping.Wrap
                };

                MyItemsControl.Items.Clear();
                MyItemsControl.Items.Add(placeholder);
                return;
            }

            MyItemsControl.Items.Clear();
            foreach (var scammer in scammers)
            {
                MyItemsControl.Items.Add(CreateScammerCard(scammer));
            }
        }
        private Border CreateScammerCard(Scammer scammer)
        {
            var border = new Border
            {
                HorizontalAlignment = HorizontalAlignment.Stretch,
                VerticalAlignment = VerticalAlignment.Top,
                Background = new SolidColorBrush(Color.FromRgb(45, 45, 45)),
                CornerRadius = new CornerRadius(10),
                Padding = new Thickness(10),
                Margin = new Thickness(0, 0, 0, 10),
                BorderBrush = new SolidColorBrush(Color.FromRgb(64, 64, 64)),
                BorderThickness = new Thickness(1)
            };

            var grid = new Grid();
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

            var img = new Image
            {
                Width = 80,
                Height = 80,
                Margin = new Thickness(0, 0, 10, 0),
                Stretch = Stretch.UniformToFill
            };

            if (!string.IsNullOrWhiteSpace(scammer.ImageBase64))
            {
                string imageKey = scammer.ImageBase64.Trim().ToLower();

                if (DefaultImages.ContainsKey(imageKey))
                {
                    string defaultBase64 = DefaultImages[imageKey];

                    if (!string.IsNullOrEmpty(defaultBase64))
                    {
                        byte[] bytes = Convert.FromBase64String(defaultBase64);
                        using (var ms = new MemoryStream(bytes))
                        {
                            var bitmap = new BitmapImage();
                            bitmap.BeginInit();
                            bitmap.CacheOption = BitmapCacheOption.OnLoad;
                            bitmap.StreamSource = ms;
                            bitmap.EndInit();
                            img.Source = bitmap;
                        }
                    }
                }
                else
                {
                    try
                    {
                        byte[] bytes = Convert.FromBase64String(scammer.ImageBase64);
                        using (var ms = new MemoryStream(bytes))
                        {
                            var bitmap = new BitmapImage();
                            bitmap.BeginInit();
                            bitmap.CacheOption = BitmapCacheOption.OnLoad;
                            bitmap.StreamSource = ms;
                            bitmap.EndInit();
                            img.Source = bitmap;
                        }
                    }
                    catch
                    {
                    }
                }
            }


            Brush statusBrush = Brushes.LightGray;

            string statusLabel = scammer.Status.ToString().Replace("PermanentlyShutdown", "Permanently Shutdown");
            if (scammer.Status == ScammerStatus.PermanentlyShutdown)
                statusLabel = "Permanently\nShutdown";
            if (scammer.Status == ScammerStatus.BusyLine)
                statusLabel = "Busy Line";

            switch (scammer.Status)
            {
                case ScammerStatus.Operating:
                    statusBrush = new SolidColorBrush(Color.FromRgb(0, 200, 0)); // green
                    break;
                case ScammerStatus.BusyLine:
                    statusBrush = new SolidColorBrush(Color.FromRgb(255, 200, 0)); // yellow
                    break;
                case ScammerStatus.Closed:
                    statusBrush = new SolidColorBrush(Color.FromRgb(255, 120, 0)); // orange
                    break;
                case ScammerStatus.PermanentlyShutdown:
                    statusBrush = new SolidColorBrush(Color.FromRgb(255, 50, 50)); // red
                    break;
            }

            var stack = new StackPanel();
            stack.HorizontalAlignment = HorizontalAlignment.Stretch;
            stack.Children.Add(new TextBlock { Text = scammer.Name, Foreground = Brushes.White, FontSize = 16, FontWeight = FontWeights.Bold,
                TextWrapping = TextWrapping.NoWrap
            });
            stack.Children.Add(new TextBlock { Text = $"Number: {scammer.Number}", Foreground = Brushes.Gray, Margin = new Thickness(0, 4, 0, 0),
                TextWrapping = TextWrapping.NoWrap
            });
            stack.Children.Add(new TextBlock { Text = $"Status: {statusLabel}", Foreground = statusBrush, Margin = new Thickness(0, 4, 0, 0), FontWeight = FontWeights.SemiBold,
                TextWrapping = TextWrapping.NoWrap
            });

            grid.Children.Add(img);
            grid.Children.Add(stack);
            Grid.SetColumn(stack, 1);
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

            var modifyButton = new Button
            {
                Content = "Modify",
                Width = 75,
                Height = 30,
                Margin = new Thickness(10, 0, 0, 0),
                Background = new SolidColorBrush(Color.FromRgb(60, 100, 180)),
                Foreground = Brushes.White,
                Cursor = Cursors.Hand
            };

            modifyButton.Click += (sender, e) =>
            {
                e.Handled = true;

                AddContact editWindow = new AddContact(scammer);
                editWindow.ShowDialog();

                LoadScammersFromXml("scammers.xml");
            };

            grid.Children.Add(modifyButton);
            Grid.SetColumn(modifyButton, 2);

            var removeButton = new Button
            {
                Content = "X",
                Width = 45,
                Height = 30,
                Margin = new Thickness(10, 0, 0, 0),
                Background = new SolidColorBrush(Color.FromRgb(160, 40, 40)),
                Foreground = Brushes.White,
                Cursor = Cursors.Hand
            };

            removeButton.Click += (sender, e) =>
            {
                e.Handled = true;

                RemoveScammerFromXml(scammer);
                LoadScammersFromXml("scammers.xml");
            };

            grid.Children.Add(removeButton);
            Grid.SetColumn(removeButton, 3);

            border.Child = grid;
            border.MouseLeftButtonUp += (sender, e) =>
            {
                e.Handled = true;
                CardClicked(scammer);
            };

            return border;
        }
        private void RemoveScammerFromXml(Scammer scammer)
        {
            string path = "scammers.xml";

            if (!File.Exists(path))
                return;

            XDocument doc = XDocument.Load(path);

            XElement? match = doc.Descendants("Scammer")
                .FirstOrDefault(x =>
                    ((string?)x.Element("Name") ?? "") == scammer.Name &&
                    ((string?)x.Element("Number") ?? "") == scammer.Number
                );

            if (match != null)
            {
                match.Remove();
                doc.Save(path);
            }
        }
        private void CreateBase64Img(string base64OrKeyword, Image target)
        {
            if (string.IsNullOrWhiteSpace(base64OrKeyword) || target == null) return;

            string key = base64OrKeyword.Trim().ToLowerInvariant();
            if (DefaultImages.TryGetValue(key, out var dictBase64) && !string.IsNullOrWhiteSpace(dictBase64))
            {
                base64OrKeyword = dictBase64;
            }

            try
            {
                byte[] bytes = Convert.FromBase64String(base64OrKeyword);
                using (var ms = new MemoryStream(bytes))
                {
                    var bmp = new BitmapImage();
                    bmp.BeginInit();
                    bmp.CacheOption = BitmapCacheOption.OnLoad;
                    bmp.StreamSource = ms;
                    bmp.EndInit();
                    bmp.Freeze();
                    target.Source = bmp;
                }
            }
            catch (FormatException)
            {
                target.Source = null;
            }
        }


        private void CardClicked(Scammer scammer)
        {
            foreach (var child in MainCanvas.Children)
            {
                if (child is TextBlock tb && tb.Name == "scammerName")
                {
                    tb.Text = scammer.Name;
                }

                if (child is TextBlock tb2 && tb2.Name == "scammerNumber")
                {
                    tb2.Text = scammer.Number;
                }

                if (child is Image tb3 && tb3.Name == "profile")
                {
                   CreateBase64Img(scammer.ImageBase64, tb3);
                }

                if (child is Button tb4 && tb4.Name == "startSessionButton")
                {
                    tb4.Cursor = Cursors.Hand;
                    tb4.Opacity = 1.0;

                }

            }

        }

        private SessionWindow? activeSessionWindow = null;

        private void Session_Start(object sender, RoutedEventArgs e)
        {
            if (sender is not Button btn)
                return;

            string number = "";

            foreach (var child in MainCanvas.Children)
            {
                if (child is TextBlock tb && tb.Name == "scammerNumber")
                {
                    number = tb.Text;
                    break;
                }
            }

            if (number == "Number will appear here." || string.IsNullOrWhiteSpace(number))
                return;

            if (activeSessionWindow == null)
            {
                btn.Content = "Stop Session";
                btn.Background = Brushes.DarkRed;
                btn.Foreground = Brushes.White;
                activeSessionWindow = new SessionWindow();
                activeSessionWindow.Show();

                activeSessionWindow.Closed += (s, args) =>
                {
                    btn.Content = "Start Session";
                    btn.Background = Brushes.DarkGreen;
                    btn.Foreground = Brushes.White;
                    activeSessionWindow.EndSession();
                    activeSessionWindow = null;
                };
            }
            else
            {
                btn.Content = "Start Session";
                btn.Background = Brushes.DarkGreen;
                btn.Foreground = Brushes.White;
                activeSessionWindow.EndSession();
                activeSessionWindow.Close();
                activeSessionWindow = null;
            }
        }
        private void Add_Click(object sender, RoutedEventArgs e)
        {
            AddContact window = new AddContact();
            window.Show();
        }
    }
}
